mapper.select:
select id ,project_id,product_demand_id,biz_demand_id,user_name,user_id, type,is_deleted,create_man ,create_date ,modify_man ,modify_date
from person
where is_deleted = false
and project_id = #{projectId}
and product_demand_id = #{productDemandId}
and biz_demand_id = #{bizDemandId}
and type = #{type}
